Here is the commit message:
loop: remove the unused inode variable in loop_configure

Remove the inode variable now that the last user is gone.

Fixes: a17ece76bcfe ("loop: regularize upgrading the block size for direct I/O")
Reported-by: kernel test robot <lkp@intel.com>
Signed-off-by: Christoph Hellwig <hch@lst.de>
Link: https://lore.kernel.org/r/20240705053114.2042976-1-hch@lst.de
Signed-off-by: Jens Axboe <axboe@kernel.dk>

Here is the root cause:
The root cause of the bug was the presence of an unused `inode` variable in the `loop_configure` function of the loop device driver. This variable was declared and assigned but not utilized, which could lead to confusion and potential maintenance issues in the code. The removal of this variable indicates that it was no longer necessary following a previous change that eliminated its last usage.

Here is the patch:

 static int loop_configure(struct loop_device *lo, blk_mode_t mode,
 			  struct block_device *bdev,
 			  const struct loop_config *config)
 {
 	struct file *file = fget(config->fd);
-	struct inode *inode;
 	struct address_space *mapping;
 	int error;
 	loff_t size;
 	bool partscan;
 	bool is_loop;

 	if (!file)
 		return -EBADF;
 	is_loop = is_loop_device(file);

 	/* This is safe, since we have a reference from open(). */
 	__module_get(THIS_MODULE);

 	/*
 	 * If we don't hold exclusive handle for the device, upgrade to it
 	 * here to avoid changing device under exclusive owner.
 	 */
 	if (!(mode & BLK_OPEN_EXCL)) {
 		error = bd_prepare_to_claim(bdev, loop_configure, NULL);
 		if (error)
 			goto out_putf;
 	}

 	error = loop_global_lock_killable(lo, is_loop);
 	if (error)
 		goto out_bdev;

 	error = -EBUSY;
 	if (lo->lo_state != Lo_unbound)
 		goto out_unlock;

 	error = loop_validate_file(file, bdev);
 	if (error)
 		goto out_unlock;

 	mapping = file->f_mapping;
-	inode = mapping->host;

 	if ((config->info.lo_flags & ~LOOP_CONFIGURE_SETTABLE_FLAGS) != 0) {
 		error = -EINVAL;
 		goto out_unlock;
 	}

 	if (config->block_size) {
 		error = blk_validate_block_size(config->block_size);
 		if (error)
 			goto out_unlock;
 	}

 	error = loop_set_status_from_info(lo, &config->info);
 	if (error)
 		goto out_unlock;

 	if (!(file->f_mode & FMODE_WRITE) || !(mode & BLK_OPEN_WRITE) ||
 	    !file->f_op->write_iter)
 		lo->lo_flags |= LO_FLAGS_READ_ONLY;

 	if (!lo->workqueue) {
 		lo->workqueue = alloc_workqueue("loop%d",
 						WQ_UNBOUND | WQ_FREEZABLE,
 						0, lo->lo_number);
 		if (!lo->workqueue) {
 			error = -ENOMEM;
 			goto out_unlock;
 		}
 	}

 	/* suppress uevents while reconfiguring the device */
 	dev_set_uevent_suppress(disk_to_dev(lo->lo_disk), 1);

 	disk_force_media_change(lo->lo_disk);
 	set_disk_ro(lo->lo_disk, (lo->lo_flags & LO_FLAGS_READ_ONLY) != 0);

 	lo->use_dio = lo->lo_flags & LO_FLAGS_DIRECT_IO;
 	lo->lo_device = bdev;
 	lo->lo_backing_file = file;
 	lo->old_gfp_mask = mapping_gfp_mask(mapping);
 	mapping_set_gfp_mask(mapping, lo->old_gfp_mask & ~(__GFP_IO|__GFP_FS));

 	error = loop_reconfigure_limits(lo, config->block_size);
 	if (WARN_ON_ONCE(error))
 		goto out_unlock;

 	loop_update_dio(lo);
 	loop_sysfs_init(lo);

 	size = get_loop_size(lo, file);
 	loop_set_size(lo, size);

 	/* Order wrt reading lo_state in loop_validate_file(). */
 	wmb();

 	lo->lo_state = Lo_bound;
 	if (part_shift)
 		lo->lo_flags |= LO_FLAGS_PARTSCAN;
 	partscan = lo->lo_flags & LO_FLAGS_PARTSCAN;
 	if (partscan)
 		clear_bit(GD_SUPPRESS_PART_SCAN, &lo->lo_disk->state);

 	/* enable and uncork uevent now that we are done */
 	dev_set_uevent_suppress(disk_to_dev(lo->lo_disk), 0);

 	loop_global_unlock(lo, is_loop);
 	if (partscan)
 		loop_reread_partitions(lo);

 	if (!(mode & BLK_OPEN_EXCL))
 		bd_abort_claiming(bdev, loop_configure);

 	return 0;

 out_unlock:
 	loop_global_unlock(lo, is_loop);
 out_bdev:
 	if (!(mode & BLK_OPEN_EXCL))
 		bd_abort_claiming(bdev, loop_configure);
 out_putf:
 	fput(file);
 	/* This is safe: open() is still holding a reference. */
 	module_put(THIS_MODULE);
 	return error;
 }



